import re,html
F="/home/claude/nori-brand/fonts/"
def fx(s):
    s=html.escape(s)
    s=re.sub(r'[A-Za-z](?:[A-Za-z0-9 ./&+\-]*[A-Za-z0-9])?',lambda m:'<bdi dir="ltr">'+m.group(0)+'</bdi>',s)
    s=re.sub(r'\[([^\]]+)\]',r'<span class="f">[\1]</span>',s)
    return s
