def block(title,items):
    return f'<div class="pb"><div class="ph">{fx(title)}</div><ul>'+''.join(f'<li>{fx(i)}</li>' for i in items)+'</ul></div>'
# plain-text copies (for the page and for checking)
def plain(intro,secs,end):
    t=intro+"\n\n"+"\n\n".join(h+"\n"+"\n".join("• "+i for i in it) for h,it in secs)
    return t+("\n\n"+end if end else "")
open("prompt.txt","w").write(plain(PROMPT_INTRO,SECTIONS,PROMPT_END)+"\n")
open("addon.txt","w").write(plain("أضف للطلب السابق (أو الصقه بآخر البرومبت):",ADDON,"")+"\n")

def page(n,body,cls=""):
    return f'''<section class="pg {cls}"><header><img class="wm" src="wm.svg"><span class="ey">CLAUDE → FIGMA</span></header>{body}<footer><span>نوري | NORI</span><span class="pn">{n:02d}</span></footer></section>'''
def ch(num,title,sub=""):
    return f'<div class="ch"><span class="no">{num}</span><h2>{title}</h2>'+(f'<p class="sub">{sub}</p>' if sub else '')+'</div>'

